   362   * The code is locale *independent* and does *not* change the locale.
   363   * It should be thread safe.
   364   */
   365  static int simple_str_to_doublestr(const char *from, char *result, char **to)
   366  {
   367      char *start = NULL, *end = NULL, *cur = (char *)from;
