   373      double dtest;
   374
   375      /*sanity checks */
   376      if (!from || !result) {
   377          return 1;
   378      }
   379
   380      /*skip the white spaces at the beginning */
   381      while (*cur && isspace((int)*cur))
   382          cur++;
   383
   384      start = cur;
   385      /* copy the part that looks like a double into result.
   386       * during the copy, we give ourselves a chance to convert the '.'
   387       * into the decimal separator of the current locale.
   388       */
   389      while (*cur && (isdigit((int)*cur) || *cur == '.' || *cur == '+' || *cur == '-')) {
   390          ++cur;
   391      }
   392      end = cur;
   393      if (end - start + 1 > 100) {
   394          /*huh hoh, number is too big. getting out */
   395          return 1;
   396      }
   397
   398      /* copy the float number string into tmp_buf, and take
   399       * care to have the (optional) decimal separator be the one
   400       * of the current locale.
   401       */
   402  #if !defined(HAVE_GETNUMBERFORMAT)
   403      for (i = 0; i < end - from; ++i) {
   404          if (start[i] == '.' && loc_data && loc_data->decimal_point && loc_data->decimal_point[0]
   405              && loc_data->decimal_point[0] != '.') {
   406              /*replace '.' by the digit separator of the current locale */
   407              result[i] = loc_data->decimal_point[0];
   408          } else {
   409              result[i] = start[i];
   410          }
   411      }
   412  #else
   413      GetNumberFormat(LOCALE_SYSTEM_DEFAULT, 0, start, NULL, result, TMP_NUM_SIZE);
   414  #endif
   415      if (to) {
   416          *to = end;
   417      }
   418
   419      /* now try to convert to a floating point number, to check for validity only */
   420      if (sscanf(result, "%lf", &dtest) != 1) {
   421          return 1;
   422      }
   423      return 0;
   424  }
