set +e
curl --connect-timeout 10 --max-time 90 --fail-with-body -sS \
  -X POST "${SERVER_URL}/submit-vul" \
  -F 'metadata={"task_id": "arvo:47986", "agent_id": "eab13a490b4d459bbfeb9eedd21ee4d8", "checksum": "8158e778b5d72037096cafa79945b4a4099f0ac9309eb212023dd75c76eedf22", "require_flag": false}' \
  -F "file=@${POC_FILE}" \
  -F "trace=@${TRACE_FILE};type=application/json" | tee "$RESPONSE_FILE"
